import sys

def find_suffixes(s):
    n = len(s)
    suffixes = set()

    for i in range(5, n):
        for j in range(i - 2, i + 1):
            if j + 2 <= n:
                suffix = s[j:j+2]
                if j - 2 >= 5 and s[j-2:j] != suffix:
                    suffixes.add(suffix)
                elif j - 2 < 5:
                    suffixes.add(suffix)
            if j + 3 <= n:
                suffix = s[j:j+3]
                if j - 2 >= 5 and s[j-2:(j+1)] != suffix:
                    suffixes.add(suffix)
                elif j - 2 <= 5:
                    suffixes.add(suffix)

    sorted_suffixes = sorted(suffixes)
    return len(sorted_suffixes), sorted_suffixes

def main():
    import sys
    s = sys.stdin.read().strip()
    count, suffixes = find_suffixes(s)
    print(count)
    for suffix in suffixes:
        print(suffix)

if __name__ == "__main__":
    main()
